import unittest
from decimal import Decimal

from kitty.errors import KittyError
from kitty.money import (allocate, convert, fmt, parse_amount, parse_currency,
                         parse_date, parse_number)


class MoneyTests(unittest.TestCase):
    def test_parse_amount_accepts(self):
        for t, v in [("45", "45"), ("45.5", "45.5"), ("45.50", "45.50"), ("0.01", "0.01")]:
            self.assertEqual(parse_amount(t), Decimal(v))

    def test_parse_amount_refuses(self):
        for t in ["abc", "-5", "0", "0.00", "1e3", "12.345", ".5", "45.", "+5",
                  "", " 5", "nan", "inf", "٣"]:
            with self.assertRaises(KittyError, msg=t):
                parse_amount(t)

    def test_parse_number(self):
        self.assertEqual(parse_number("0.923456"), Decimal("0.923456"))
        for t in ["0", ".5", "1e3", "-1", "+2", "x"]:
            with self.assertRaises(KittyError, msg=t):
                parse_number(t)

    def test_parse_currency(self):
        self.assertEqual(parse_currency("usd"), "USD")
        for t in ["US", "USDD", "U$D", "123"]:
            with self.assertRaises(KittyError, msg=t):
                parse_currency(t)

    def test_parse_date(self):
        self.assertEqual(parse_date("2026-07-14"), "2026-07-14")
        for t in ["2026-02-30", "2026-7-14", "14/07/2026", "20260714"]:
            with self.assertRaises(KittyError, msg=t):
                parse_date(t)

    def test_fmt(self):
        self.assertEqual(fmt(Decimal("20.7")), "20.70")
        self.assertEqual(fmt(Decimal("-20.70")), "-20.70")
        self.assertEqual(fmt(Decimal("-0.00")), "0.00")
        self.assertEqual(fmt(Decimal("0")), "0.00")

    def test_convert_half_up(self):
        self.assertEqual(convert(Decimal("45.00"), Decimal("0.92")), Decimal("41.40"))
        self.assertEqual(convert(Decimal("0.25"), Decimal("0.5")), Decimal("0.13"))
        self.assertEqual(convert(Decimal("10"), Decimal("1")), Decimal("10.00"))

    def test_allocate_equal(self):
        r = allocate(Decimal("10.00"), [("Alice", Decimal(1)), ("Bob", Decimal(1)), ("Cara", Decimal(1))])
        self.assertEqual(list(r.items()), [("Alice", Decimal("3.34")), ("Bob", Decimal("3.33")),
                                           ("Cara", Decimal("3.33"))])

    def test_allocate_weighted(self):
        r = allocate(Decimal("10.00"), [("A", Decimal(1)), ("B", Decimal(2))])
        self.assertEqual(r, {"A": Decimal("3.34"), "B": Decimal("6.66")})

    def test_allocate_order_matters(self):
        r = allocate(Decimal("10.00"), [("Cara", Decimal(1)), ("Alice", Decimal(1)), ("Bob", Decimal(1))])
        self.assertEqual(r["Cara"], Decimal("3.34"))
        self.assertEqual(r["Alice"], Decimal("3.33"))

    def test_one_cent_three_ways(self):
        r = allocate(Decimal("0.01"), [("A", Decimal(1)), ("B", Decimal(1)), ("C", Decimal(1))])
        self.assertEqual(list(r.values()), [Decimal("0.01"), Decimal("0.00"), Decimal("0.00")])

    def test_allocate_sums_exactly(self):
        r = allocate(Decimal("41.41"), [("A", Decimal("60")), ("B", Decimal("40"))])
        self.assertEqual(sum(r.values()), Decimal("41.41"))
        self.assertEqual(r, {"A": Decimal("24.85"), "B": Decimal("16.56")})


if __name__ == "__main__":
    unittest.main()

