import unittest
from decimal import Decimal as D

from kitty.errors import KittyError
from kitty.splits import split_weights

MEMBERS = ["Alice", "Bob", "Cara"]


def res(name):
    for m in MEMBERS:
        if m.casefold() == name.casefold():
            return m
    raise KittyError("no member named {!r}".format(name))


class SplitTests(unittest.TestCase):
    def test_equal_uses_join_order(self):
        self.assertEqual(split_weights("equal", None, D("10"), MEMBERS, res),
                         [("Alice", 1), ("Bob", 1), ("Cara", 1)])

    def test_equal_with_no_members_refused(self):
        with self.assertRaises(KittyError):
            split_weights("equal", None, D("10"), [], res)

    def test_among_typed_order_and_case(self):
        self.assertEqual(split_weights("among", "cara,ALICE", D("10"), MEMBERS, res),
                         [("Cara", 1), ("Alice", 1)])

    def test_duplicate_names_differing_in_case_refused(self):
        with self.assertRaises(KittyError):
            split_weights("among", "alice,ALICE", D("10"), MEMBERS, res)

    def test_unknown_name_refused(self):
        with self.assertRaises(KittyError):
            split_weights("among", "Alice,Zed", D("10"), MEMBERS, res)

    def test_empty_among_part_refused(self):
        for spec in ["", "Alice,", ",Bob", "Alice,,Bob"]:
            with self.assertRaises(KittyError, msg=spec):
                split_weights("among", spec, D("10"), MEMBERS, res)

    def test_exact_must_sum(self):
        self.assertEqual(split_weights("exact", "Alice=30,Bob=20", D("50"), MEMBERS, res),
                         [("Alice", D("30")), ("Bob", D("20"))])
        with self.assertRaises(KittyError):
            split_weights("exact", "Alice=30,Bob=19.99", D("50"), MEMBERS, res)

    def test_percent_must_sum_to_100(self):
        self.assertEqual(split_weights("percent", "Alice=60,Bob=40", D("10"), MEMBERS, res),
                         [("Alice", D("60")), ("Bob", D("40"))])
        with self.assertRaises(KittyError):
            split_weights("percent", "Alice=60,Bob=39", D("10"), MEMBERS, res)

    def test_shares_values(self):
        self.assertEqual(split_weights("shares", "Alice=1,Bob=2", D("10"), MEMBERS, res),
                         [("Alice", D("1")), ("Bob", D("2"))])

    def test_bad_pair_syntax_refused(self):
        for spec in ["Alice", "Alice=", "=3", "Alice=1=2", "Alice=1,,Bob=1", "Alice=x",
                     "Alice=-1", "Alice=0", "Alice=1,alice=2"]:
            with self.assertRaises(KittyError, msg=spec):
                split_weights("shares", spec, D("10"), MEMBERS, res)


if __name__ == "__main__":
    unittest.main()
